    {
        var account = new AccountState(0, 0);
        var (r, d) = Deposit(account, N(0, 0, 0), N(5, 5, 5), jammed);

        AssertRefused(AtmStatus.InvalidAmount, r, d, account, N(5, 5, 5));
    }

